# 「0 や空なら既定値」という折衷パターン。値の出どころを条件式で明示します。
variable "container_cpu" {
  default = 0 # 0 は「未指定」の意味で使う流儀
}

locals {
  default_cpu   = 256
  effective_cpu = var.container_cpu > 0 ? var.container_cpu : local.default_cpu
  cpu_source    = var.container_cpu > 0 ? "variable" : "hardcoded-default"
}

output "cpu_source" {
  value = local.cpu_source
}

output "effective_cpu" {
  value = local.effective_cpu
}

exercise.answer:
# cpu は var.container_cpu が 0(未指定)なので条件式の右側 256 に確定します。
# memory は var.container_memory の default 1024 がそのまま使われます。
# 「var. を見たら default と上書き経路を確認する」のが読解の基本です。
variable "container_cpu" {
  default = 0
}

variable "container_memory" {
  default = 1024
}

locals {
  cpu    = var.container_cpu > 0 ? var.container_cpu : 256
  memory = var.container_memory
}

output "cpu" {
  value = local.cpu
}

output "cpu_source" {
  value = var.container_cpu > 0 ? "variable" : "hardcoded-default"
}

output "memory" {
  value = local.memory
}

output "memory_source" {
  value = "variable-default"
}
